-- Testbench: b10 (one scan chain, 17 cells) tested by the one-chain self-test stumps1.
-- Generated by make_bist_tb.py from b10_scan.v and b10_scan.spf.
-- Only this file depends on the circuit: it connects the ports of b10 to stumps1.
--   TPG output 0 -> test_si (scan-in); 1..11 -> v_in(0), v_in(1), v_in(2), v_in(3), r_button, g_button, key, start, test, rts, rtr
--   MISR inputs    0 -> v_out[3] (scan-out); 1..5 -> the other outputs
--   (v_out(0), v_out(1), v_out(2), cts, ctr)
-- Tester timing as in the testbenches of the previous labs: the self-test logic
-- changes at the beginning of each 100 ns cycle, the clock of b10 rises 50 ns later.
-- The clock of b10 stops at the end of the self-test.
-- At the end it prints the number of test cycles, the signature and GO/NOGO.

library ieee;
use ieee.std_logic_1164.all;

entity tb_b10_scan_bist is
    generic (
        N_PATTERNS       : positive := 50;
        CAPTURE          : positive := 1;
        LFSR_SEED        : integer  := 1234;
        PHASE_SHIFTER    : integer  := 0;
        MISR_MODE        : integer  := 1;
        GOLDEN_SIGNATURE : std_logic_vector(31 downto 0) := x"00000000"
    );
end tb_b10_scan_bist;

architecture tb of tb_b10_scan_bist is
    constant clock_t1     : time := 50 ns;
    constant clock_t2     : time := 30 ns;
    constant clock_t3     : time := 20 ns;
    constant apply_period : time := 100 ns;

    signal tester_clock, bist_clock, dut_clock_free : std_logic := '0';
    signal dut_clock_en : std_logic := '1';
    signal rst_n, start : std_logic;
    signal tpg : std_logic_vector(11 downto 0);
    signal pos : std_logic_vector(5 downto 0);
    signal scan_en, testing, test_over, go_nogo : std_logic;
    signal signature : std_logic_vector(31 downto 0);
    signal s_v_in : std_logic_vector(3 downto 0);
    signal s_v_out : std_logic_vector(3 downto 0);
    signal s_r_button : std_logic;
    signal s_g_button : std_logic;
    signal s_key : std_logic;
    signal s_start : std_logic;
    signal s_reset : std_logic;
    signal s_test : std_logic;
    signal s_rts : std_logic;
    signal s_rtr : std_logic;
    signal s_clock : std_logic;
    signal s_test_si : std_logic;
    signal s_test_se : std_logic;
    signal s_cts : std_logic;
    signal s_ctr : std_logic;
begin

    u_bist : entity work.stumps1
        generic map (CHAIN_LEN => 17, N_PATTERNS => N_PATTERNS, CAPTURE => CAPTURE,
                     NTPG => 12, NPOS => 6, LFSR_SEED => LFSR_SEED, MISR_SEED => 1234,
                     PHASE_SHIFTER => PHASE_SHIFTER, MISR_MODE => MISR_MODE,
                     GOLDEN_SIGNATURE => GOLDEN_SIGNATURE)
        port map (clk_i => bist_clock, rst_ni => rst_n, start_i => start,
                  tpg_o => tpg, scan_en_o => scan_en, pos_i => pos,
                  signature_o => signature, testing_o => testing,
                  test_over_o => test_over, go_nogo_o => go_nogo);

    u_b10 : entity work.b10
        port map (
                  v_in => s_v_in,
                  v_out => s_v_out,
                  r_button => s_r_button,
                  g_button => s_g_button,
                  key => s_key,
                  start => s_start,
                  reset => s_reset,
                  test => s_test,
                  rts => s_rts,
                  rtr => s_rtr,
                  clock => s_clock,
                  test_si => s_test_si,
                  test_se => s_test_se,
                  cts => s_cts,
                  ctr => s_ctr);

    -- self-test -> circuit
    s_test_si <= tpg(0);
    s_v_in(0) <= tpg(1);
    s_v_in(1) <= tpg(2);
    s_v_in(2) <= tpg(3);
    s_v_in(3) <= tpg(4);
    s_r_button <= tpg(5);
    s_g_button <= tpg(6);
    s_key <= tpg(7);
    s_start <= tpg(8);
    s_test <= tpg(9);
    s_rts <= tpg(10);
    s_rtr <= tpg(11);
    s_test_se <= scan_en;

    -- circuit -> MISR (scan-out in position 0)
    pos(0) <= s_v_out(3);
    pos(1) <= s_v_out(0);
    pos(2) <= s_v_out(1);
    pos(3) <= s_v_out(2);
    pos(4) <= s_cts;
    pos(5) <= s_ctr;

    -- clocks and reset
    process begin
        loop
            wait for clock_t1; tester_clock <= '1';
            wait for clock_t2; tester_clock <= '0';
            wait for clock_t3;
        end loop;
    end process;
    dut_clock_free <= transport tester_clock after apply_period;
    bist_clock     <= transport tester_clock after apply_period - clock_t1;

    -- The clock of b10 stops when the self-test ends: after the test the circuit must
    -- not run in functional mode, or the eVCD would contain cycles that TestMAX observes
    -- but the MISR does not compact.
    process(testing) begin
        if falling_edge(testing) then dut_clock_en <= '0'; end if;
    end process;
    s_clock <= dut_clock_free and dut_clock_en;

    s_reset <= '0', '1' after clock_t1, '0' after clock_t1 + clock_t2;
    rst_n <= '0', '1' after clock_t1 + clock_t2;
    start <= '1';

    -- report
    process
        variable cycles : natural := 0;
    begin
        wait until rising_edge(bist_clock) and testing = '1';
        while testing = '1' loop
            cycles := cycles + 1;
            wait until rising_edge(bist_clock);
        end loop;
        wait until test_over = '1';
        wait for apply_period;
        report "BIST: number of test cycles = " & integer'image(cycles);
        report "BIST: signature = " & to_hstring(signature);
        report "BIST: golden    = " & to_hstring(GOLDEN_SIGNATURE);
        if go_nogo = '1' then report "BIST: result = GO"; else report "BIST: result = NOGO"; end if;
        std.env.stop;
    end process;

end tb;
